document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('tr').forEach(function(e){let t=null!==e.querySelector('.submitapprove'),o=null!==e.querySelector('.submitunapprove');t&&o?e.style.backgroundColor='#FFFFE0':t&&(e.style.backgroundColor='#FAAFAA')});document.querySelectorAll('.actions select[name^="action"]').forEach(function(e){var t=document.createElement('option');t.value='wpau_bulk_approve',t.textContent=wp_approve_user.approve,e.appendChild(t);var o=document.createElement('option');o.value='wpau_bulk_unapprove',o.textContent=wp_approve_user.unapprove,e.appendChild(o)})});
